// What a single damage entry reimburses, before the policy's cap is applied.
// The deductible is charged once per damaged item, not once per incident, so
// it belongs here rather than at the incident level.
//
// Takes the whole policy rather than the damage alone because the special
// reimbursement clauses grade the payout by the *damaged item's* properties
// (enchantment, material), which only the policy can resolve from itemType.
const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
const HALVED_REIMBURSEMENT_PERCENT = 50;

const reimbursementFor = (item: Item | undefined, amount: number): number =>
  (item?.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT
    ? percentOf(amount, HALVED_REIMBURSEMENT_PERCENT)
    : amount;

const payoutForDamage = (policy: IssuedPolicy, damage: Damage): number => {
  const damagedItem = policy.items.find(
    (item) => item.type === damage.itemType,
  );

  return (
    reimbursementFor(damagedItem, damage.amount) - DEDUCTIBLE_PER_DAMAGE
  );
};

